UPDATE wa_group wa_group INNER JOIN ( SELECT DISTINCT preview.tenant_id, preview.group_jid FROM group_link_preview preview WHERE preview.tenant_id = #{tenantId} AND preview.group_link_id IN
#{groupLinkId}
AND preview.group_jid IS NOT NULL ) deleted_alias ON deleted_alias.tenant_id = wa_group.tenant_id AND deleted_alias.group_jid = wa_group.group_jid SET wa_group.deleted_at = #{deletedAt}, wa_group.updated_at = GREATEST(wa_group.updated_at, #{deletedAt}) WHERE wa_group.tenant_id = #{tenantId} AND wa_group.deleted_at IS NULL AND NOT EXISTS ( SELECT 1 FROM group_link active_link INNER JOIN group_link_preview active_preview ON active_preview.tenant_id = active_link.tenant_id AND active_preview.group_link_id = active_link.id WHERE active_link.tenant_id = wa_group.tenant_id AND active_link.deleted_at IS NULL AND active_preview.group_jid = wa_group.group_jid )

UPDATE wa_group wa_group INNER JOIN ( SELECT DISTINCT deleted_link.tenant_id, preview.group_jid FROM group_link deleted_link INNER JOIN group_link_preview preview ON preview.tenant_id = deleted_link.tenant_id AND preview.group_link_id = deleted_link.id WHERE deleted_link.tenant_id = #{tenantId} AND deleted_link.label_id IN
#{labelId}
AND preview.group_jid IS NOT NULL ) deleted_alias ON deleted_alias.tenant_id = wa_group.tenant_id AND deleted_alias.group_jid = wa_group.group_jid SET wa_group.deleted_at = #{deletedAt}, wa_group.updated_at = GREATEST(wa_group.updated_at, #{deletedAt}) WHERE wa_group.tenant_id = #{tenantId} AND wa_group.deleted_at IS NULL AND NOT EXISTS ( SELECT 1 FROM group_link active_link INNER JOIN group_link_preview active_preview ON active_preview.tenant_id = active_link.tenant_id AND active_preview.group_link_id = active_link.id WHERE active_link.tenant_id = wa_group.tenant_id AND active_link.deleted_at IS NULL AND active_preview.group_jid = wa_group.group_jid )

